<div class="row"><div class="col-12"><div class="card card-primary"><div class="card-header"><h3 class="card-title">Detail Tagihan</h3></div><div class="card-body"><dl class="row"><dt class="col-sm-3">Nomor</dt><dd class="col-sm-9"><?php echo html_escape($tagihan->nomor_tagihan); ?></dd><dt class="col-sm-3">Total</dt><dd class="col-sm-9">Rp <?php echo number_format($tagihan->total, 0, ',', '.'); ?></dd><dt class="col-sm-3">Sudah Dibayar</dt><dd class="col-sm-9">Rp <?php echo number_format($tagihan->sudah_dibayar, 0, ',', '.'); ?></dd><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><?php echo html_escape($tagihan->status); ?></dd></dl><table class="table table-bordered"><thead><tr><th>Item</th><th>Jenis</th><th>Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php foreach($tagihan->items as $item): ?><tr><td><?php echo html_escape($item->nama_item); ?></td><td><?php echo html_escape($item->jenis_item); ?></td><td><?php echo html_escape($item->jumlah); ?></td><td>Rp <?php echo number_format($item->subtotal, 0, ',', '.'); ?></td></tr><?php endforeach; ?></tbody></table></div><div class="card-footer"><a href="<?php echo site_url(SITE_AREA . '/content/tagihan'); ?>" class="btn btn-default">Kembali</a></div></div></div></div>
